<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';$a=90;$b=false;$c=false;$argv=isset($argv)?$argv:array();foreach(array_slice($argv,1)as $d){$d=(string)$d;if(strpos($d,'--days=')===0){$a=max(0,(int)substr($d,7));}elseif($d==='--dry'){$b=true;}elseif($d==='--quiet'){$c=true;}}try{$e=Core\DB::pdo();if($a<=0){$f=(int)$e->query('SELECT COUNT(*) FROM app_api_logs')->fetchColumn();echo'保留期 0 = 不清理；当前流水 '.$f." 行\n";exit(0);}$g=(int)$e->query('SELECT COUNT(*) FROM app_api_logs')->fetchColumn();$h=$e->prepare('DELETE FROM app_api_logs WHERE created_at < DATE_SUB(NOW(), INTERVAL :d DAY) LIMIT 5000');$i=0;$j=0;while($j++<2000){if($b){$k=(int)$e->query('SELECT COUNT(*) FROM app_api_logs WHERE created_at < DATE_SUB(NOW(), INTERVAL '.(int)$a.' DAY)')->fetchColumn();$i=$k;break;}$h->execute(array(':d'=>$a));$l=$h->rowCount();$i+=$l;if($l<5000){break;}usleep(50000);}$m=$b?$g:($g-$i);if($c){echo($b?'dry: 将删 ':'已删 ').$i." 行\n";}else{echo($b?'[dry] 将删除':'清理完成，删除').' '.$i.' 行（保留最近 '.$a.' 天；'.$g.' → '.$m."）\n";}exit(0);}catch(\Throwable $n){fwrite(STDERR,'清理失败：'.$n->getMessage()."\n");exit(1);}